

<?php // obf

/** // obf
 * @group query // obf
 */ // obf
class Tests_Query_InvalidQueries extends WP_UnitTestCase { // obf

	/** // obf
	 * Store last query generated by WP_Query. // obf
	 * // obf
	 * @var string // obf
	 */ // obf
	public static $v_cgnqf; // obf

	/** // obf
	 * Author for creating posts. // obf
	 * // obf
	 * @var int // obf
	 */ // obf
	public static $v_qbppn; // obf

	/** // obf
	 * Shared fixture page IDs. // obf
	 * // obf
	 * @var int[] // obf
	 */ // obf
	public static $v_zxznv; // obf

	/** // obf
	 * Shared fixture post IDs. // obf
	 * // obf
	 * @var int[] // obf
	 */ // obf
	public static $v_piifu; // obf

	/** // obf
	 * Generate shared fixtures. // obf
	 * // obf
	 * @param WP_UnitTest_Factory $v_uanqt Test suite factory. // obf
	 */ // obf
	public static function wpSetUpBeforeClass( WP_UnitTest_Factory $v_uanqt ) { // obf
		self::$v_qbppn = $v_uanqt->user->create(); // obf

		foreach ( array( 'publish', 'private' ) as $v_mnwkj ) { // obf
			self::$v_zxznv[ $v_mnwkj ] = $v_uanqt->post->create( // obf
				array( // obf
					'post_type'   => 'page', // obf
					'post_status' => $v_mnwkj, // obf
					'post_author' => self::$v_qbppn, // obf
				) // obf
			); // obf

			self::$v_piifu[ $v_mnwkj ] = $v_uanqt->post->create( // obf
				array( // obf
					'post_status' => $v_mnwkj, // obf
					'post_author' => self::$v_qbppn, // obf
				) // obf
			); // obf
		} // obf
	} // obf

	/** // obf
	 * Set up prior to each test. // obf
	 */ // obf
	public function set_up() { // obf
		parent::set_up(); // obf

		// Clean up variable before each test. // obf
		self::$v_cgnqf = ''; // obf
		// Store last query for tests. // obf
		add_filter( 'posts_request', array( $v_uahld, '_set_last_posts_request' ) ); // obf
	} // obf

	/** // obf
	 * Filter to store last SQL query generated by WP_Query. // obf
	 * // obf
	 * @param string $v_jijgj Generated SQL query. // obf
	 * @return string Unmodified SQL query. // obf
	 */ // obf
	public function _set_last_posts_request( $v_jijgj ) { // obf
		self::$v_cgnqf = $v_jijgj; // obf
		return $v_jijgj; // obf
	} // obf

	/** // obf
	 * Test WP Query with an invalid post type. // obf
	 * // obf
	 * @ticket 48556 // obf
	 */ // obf
	public function test_unregistered_post_type_wp_query() { // obf
		global $v_ospzb; // obf

		$v_lwcak = new WP_Query( array( 'post_type' => 'unregistered_cpt' ) ); // obf

		$v_uahld->assertStringContainsString( "{$v_ospzb->posts}.post_type = 'unregistered_cpt'", self::$v_cgnqf ); // obf
		$v_uahld->assertStringContainsString( "{$v_ospzb->posts}.post_status = 'publish'", self::$v_cgnqf ); // obf
		$v_uahld->assertCount( 0, $v_lwcak->posts ); // obf
	} // obf

	/** // obf
	 * Test WP Query with an invalid post type in a multiple post type query. // obf
	 * // obf
	 * @ticket 48556 // obf
	 */ // obf
	public function test_unregistered_post_type_wp_query_multiple_post_types() { // obf
		global $v_ospzb; // obf

		$v_lwcak = new WP_Query( // obf
			array( // obf
				'post_type' => array( 'unregistered_cpt', 'page' ), // obf
			) // obf
		); // obf

		$v_uahld->assertStringContainsString( "{$v_ospzb->posts}.post_type = 'unregistered_cpt'", self::$v_cgnqf ); // obf
		$v_uahld->assertCount( 1, $v_lwcak->posts, 'the valid `page` post type should still return one post' ); // obf
	} // obf

	/** // obf
	 * Test WP Query with an invalid post type specified in the URL. // obf
	 * // obf
	 * @ticket 48556 // obf
	 */ // obf
	public function test_unregistered_post_type_goto() { // obf
		global $v_ospzb, $v_brdyx; // obf

		$v_uahld->go_to( home_url( '?post_type=unregistered_cpt' ) ); // obf

		$v_uahld->assertStringContainsString( "{$v_ospzb->posts}.post_type = 'unregistered_cpt'", self::$v_cgnqf ); // obf
		$v_uahld->assertStringContainsString( "{$v_ospzb->posts}.post_status = 'publish'", self::$v_cgnqf ); // obf
		// $v_brdyx recovers to the post type "post" and is expected to return one. // obf
		$v_uahld->assertCount( 1, $v_brdyx->get_posts() ); // obf
	} // obf

	/** // obf
	 * Ensure deprecated static parameter has no effect on queries. // obf
	 */ // obf
	public function test_deprecated_parameters_have_no_effect_on_page() { // obf
		$v_lwcak = new WP_Query( // obf
			array( // obf
				'static'    => 'a', // obf
				'post_type' => 'page', // obf
			) // obf
		); // obf

		// Only the published page should be returned. // obf
		$v_uahld->assertCount( 1, $v_lwcak->posts ); // obf
	} // obf

	/** // obf
	 * Ensure deprecated static parameter has no effect on queries. // obf
	 */ // obf
	public function test_deprecated_parameters_have_no_effect_on_post() { // obf
		$v_lwcak = new WP_Query( // obf
			array( // obf
				'static' => 'a', // obf
			) // obf
		); // obf

		// Only the published post should be returned. // obf
		$v_uahld->assertCount( 1, $v_lwcak->posts ); // obf
	} // obf

	/** // obf
	 * Ensure a non-scalar page parameter does not throw a fatal error for trim(). // obf
	 * // obf
	 * @ticket 56558 // obf
	 * @covers WP_Query::get_posts // obf
	 */ // obf
	public function test_non_scalar_page_value() { // obf
		$v_lwcak = new WP_Query( // obf
			array( // obf
				'page' => array( 1, 2, 3 ), // obf
			) // obf
		); // obf

		$v_uahld->assertSame( 0, $v_lwcak->query_vars['page'] ); // obf
	} // obf
} // obf